import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import os from "node:os";
import selfsigned from "selfsigned";
import { logger } from "./logger.js";

// Generate (once) and reuse a self-signed TLS cert for LAN HTTPS.
// Stored under data/tls/ so it survives restarts and can be regenerated by
// deleting the files. Self-signed => browsers show a one-time warning that
// the user accepts; after that it's HTTPS everywhere with no upgrade issues.

function certDir(dataDir) {
  return path.join(dataDir, "tls");
}

// Best-effort list of this host's LAN IPv4 addresses, so the cert's SAN
// includes them (cleaner trust prompts, and lets users trust the cert).
function lanIPv4s() {
  const out = [];
  for (const addrs of Object.values(os.networkInterfaces())) {
    for (const a of addrs || []) {
      if (a.family === "IPv4" && !a.internal) out.push(a.address);
    }
  }
  return out;
}

function buildAltNames(extraHosts) {
  const names = [{ type: 2, value: "cinevault.local" }, { type: 7, ip: "127.0.0.1" }];
  const seen = new Set(["cinevault.local", "127.0.0.1"]);
  const hosts = [...(extraHosts || []), ...lanIPv4s()];
  for (const h of hosts) {
    if (!h || seen.has(h)) continue;
    seen.add(h);
    const isIp = /^(\d{1,3}\.){3}\d{1,3}$/.test(h);
    names.push(isIp ? { type: 7, ip: h } : { type: 2, value: h });
  }
  return names;
}

export async function ensureSelfSignedCert(dataDir, extraHosts = []) {
  const dir = certDir(dataDir);
  const keyPath = path.join(dir, "key.pem");
  const certPath = path.join(dir, "cert.pem");

  if (existsSync(keyPath) && existsSync(certPath)) {
    return { key: readFileSync(keyPath, "utf8"), cert: readFileSync(certPath, "utf8") };
  }

  mkdirSync(dir, { recursive: true });

  const attrs = [{ name: "commonName", value: "cinevault.local" }];
  const pems = await selfsigned.generate(attrs, {
    days: 3650,
    keySize: 2048,
    algorithm: "sha256",
    extensions: [
      { name: "basicConstraints", cA: true },
      { name: "keyUsage", keyCertSign: true, digitalSignature: true, keyEncipherment: true },
      { name: "extKeyUsage", serverAuth: true },
      {
        name: "subjectAltName",
        altNames: buildAltNames(extraHosts),
      },
    ],
  });

  writeFileSync(keyPath, pems.private, { mode: 0o600 });
  writeFileSync(certPath, pems.cert, { mode: 0o644 });
  logger.info({ dir }, "generated self-signed TLS certificate");

  return { key: pems.private, cert: pems.cert };
}
